import math

def check_solution(m, n, p):
    # Check condition 1: m^2 + n = p^a, a >= 2
    A = m**2 + n
    if A <= 0:
        return False

    a = 0
    temp_A = A
    if temp_A == 1:
        a = 0 # Technically, A >= 1+1 = 2 since m, n >= 1
    else:
        while temp_A > 1:
            if temp_A % p != 0:
                return False
            temp_A //= p
            a += 1

    if a < 2:
        return False

    # Check condition 2: m + n^2 = p^b, b >= 2
    B = m + n**2
    if B <= 0:
        return False

    b = 0
    temp_B = B
    if temp_B == 1:
        b = 0
    else:
        while temp_B > 1:
            if temp_B % p != 0:
                return False
            temp_B //= p
            b += 1

    if b < 2:
        return False

    return True

# Test small values for m and n, fixed p=2
limit = 10
solutions = []
for m in range(1, limit + 1):
    for n in range(1, limit + 1):
        if check_solution(m, n, 2):
            solutions.append((m, n, 2))

print("Solutions for p=2 within m, n <= 10:")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found for p=2 within m, n <= 10.")

