import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_prime_and_power_of(N, p):
    if N <= 0 or p <= 1:
        return False
    if N == p: # Should not happen based on conditions a, b >= 2
        return False

    # Check if N is a power of p
    k = 0
    temp = N
    while temp > 0 and temp % p == 0:
        temp //= p
        k += 1

    # Check if N is a power of p AND k >= 2
    return temp == 1 and k >= 2

def solve_search():
    solutions = []
    primes = [2, 3, 5, 7, 11, 13]
    M_MAX = 15
    N_MAX = 15

    for p in primes:
        for m in range(1, M_MAX + 1):
            for n in range(1, N_MAX + 1):

                # Condition 1: m^2 + n = p^a, a >= 2
                N1 = m*m + n
                if not is_prime_and_power_of(N1, p):
                    continue

                # Condition 2: m + n^2 = p^b, b >= 2
                N2 = m + n*n
                if not is_prime_and_power_of(N2, p):
                    continue

                solutions.append((m, n, p))

    return solutions

solutions = solve_search()
print(f"Found solutions: {solutions}")

# Calculate the total sum
total_sum = 0
for m, n, p in solutions:
    total_sum += (m + n + p)

print(f"Total sum: {total_sum}")
